// Package popular ships a snapshot of reciter popularity, generated by
// tools/genpopular because mp3quran.net publishes no play counts.
package popular

import (
	_ "embed"
	"encoding/json"
	"strconv"
)

//go:embed popular.json
var data []byte

type Entry struct {
	Listens int  `json:"listens"`
	Known   bool `json:"known"`
}

// Load returns popularity by mp3quran reciter id.
func Load() map[int]Entry {
	var f struct {
		Reciters map[string]Entry `json:"reciters"`
	}
	out := map[int]Entry{}
	if json.Unmarshal(data, &f) != nil {
		return out
	}
	for k, v := range f.Reciters {
		if id, err := strconv.Atoi(k); err == nil {
			out[id] = v
		}
	}
	return out
}
